#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_next_wrap_around(void) {
    // Setup: create a vector with some elements
    Vector* vec = helper_create_vector(0);
    TEST_ASSERT_NOT_NULL(vec);

    // Fill vector with values 10, 20, 30
    int values[] = {10, 20, 30};
    int fill_result = helper_fill_vector(vec, values, 3);
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    // Set current index to length (3) to trigger wrap-around condition
    // The operation map doesn't have a direct set_current function,
    // but we can use vector_reset_iterator to set to 0 and then call next
    // multiple times to reach the end.
    vector_reset_iterator(vec); // sets current to 0
    // Call next 3 times to consume all elements and set current to 3
    int val1 = next(vec);
    int val2 = next(vec);
    int val3 = next(vec);
    TEST_ASSERT_EQUAL_INT(10, val1);
    TEST_ASSERT_EQUAL_INT(20, val2);
    TEST_ASSERT_EQUAL_INT(30, val3);
    // Now vec->current should be 3, equal to vec->len (3)

    // Test: call next when current == len (path 1 condition)
    int result = next(vec);
    // Should wrap around to index 0 and return value 10
    TEST_ASSERT_EQUAL_INT(10, result);

    // Verify current index was incremented after return (should be 1)
    // We can verify by calling next again and checking it returns second element
    int next_result = next(vec);
    TEST_ASSERT_EQUAL_INT(20, next_result);

    // Cleanup
    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_next_wrap_around);
    return UNITY_END();
}

